from pathlib import Path
from collections import Counter,defaultdict
from itertools import combinations
import json
root=Path(__file__).resolve().parents[1]
types=['Характеристика','Противопоставление','Разновидность','Помогает','Вызывает','Регулирует']
sources={'E02':'easy-candidates-100-interactions.json','E03':'easy-candidates-100-v2-interactions.json','E04':'independent-candidates-100-e04-interactions.json'}
exclude={('E03','Помогает','Счёт','Количество'):'Счёт помогает определить количество, а не количеству. Измерение не включено в шесть типов.',('E03','Помогает','Счёт','Пульс'):'Подсчёт помогает оценить пульс, а не работе пульса. Это измерение.',('E03','Помогает','Самостоятельность','Исследование'):'Объяснение про облегчение самостоятельного исследования повторяет значение самостоятельности и не даёт отдельного механизма помощи. Характеристика этой пары сохранена.',('E04','Помогает','Шифрование','Загрузка'):'Объяснение относится к защите данных, а не облегчению загрузки. Карты «Защита» в пуле нет.'}
additions=[dict(a='Порядок',b='Подготовка',type='Регулирует',reason='Заданный порядок подготовки определяет последовательность подготовительных действий; речь о предписанной последовательности, не случайном расположении.'),dict(a='Порядок',b='Тренировка',type='Регулирует',reason='Заданный порядок тренировки определяет очередность выполнения упражнений.'),dict(a='Порядок',b='Проверка',type='Регулирует',reason='Заданный порядок проверки определяет последовательность проверочных действий.')]
all_data={};stats={};removed=[]
for code,filename in sources.items():
 original=json.loads((root/filename).read_text());edges=[]
 for e in original['relations']:
  if e['type'] not in types:continue
  key=(code,e['type'],e['a'],e['b'])
  if key in exclude:
   removed.append((code,e,exclude[key]));continue
  e=dict(e,origin='предыдущая разметка')
  if code=='E02' and e['type']=='Характеристика':e['a'],e['b']=e['b'],e['a']
  edges.append(e)
 if code=='E02':edges.extend(dict(e,origin='добавлено при проверке шести типов') for e in additions)
 assert len(original['words'])==100
 for e in edges:assert e['a'] in original['words'] and e['b'] in original['words'] and e['a']!=e['b']
 pairs=defaultdict(set)
 for e in edges:pairs[tuple(sorted((e['a'],e['b'])))].add(e['type'])
 degree=Counter()
 for a,b in pairs:degree.update([a,b])
 counts={t:sum(t in ts for ts in pairs.values()) for t in types}
 intersections={(t,u):sum({t,u}.issubset(ts) for ts in pairs.values()) for t,u in combinations(types,2)}
 all_data[code]=dict(words=original['words'],relations=edges)
 stats[code]=dict(counts=counts,pairs=pairs,degree=degree,intersections=intersections,annotations=len(edges),multiple=sum(len(ts)>1 for ts in pairs.values()))
rows=['# Проверка трёх списков по шести типам связей','','## Область проверки','','28 сентября 2026 года. Рассмотрены три последних списка по 100 слов: E02 (первый), E03 (заменены четыре категории), E04 (заменены все категории). Старый пилот из 28 слов не смешивается с этими списками. Между списками пары не создаются: каждый остаётся отдельным пулом.','','Проверены существующие объяснения и дополнительно рассмотрены кандидаты на «Регулирует» в первых двух списках. Это пересмотр разметки, а не полный перебор 14 850 внутрисписочных пар. Нули означают «не найдено в разметке». Числа не являются эмпирическими оценками вероятности или понимания детьми.','','## Единые определения','','| Тип | Критерий |','|---|---|','| Характеристика | A описывается признаком B; направление носитель → признак. |','| Противопоставление | Значения противопоставлены по явному общему основанию; не просто отличаются. |','| Разновидность | A является видом B в принятом значении; условные трактовки сохраняют явные оговорки. |','| Помогает | A облегчает выполнение или достижение B. Не заменять B отсутствующим словом: помощь в измерении пульса не помощь пульсу. |','| Вызывает | A может приводить к возникновению B; условия и промежуточные процессы обязательно указаны. |','| Регулирует | A задаёт порядок, допуск или ограничения B. Не любое влияние, мотивация, помощь или физиологическая зависимость. |','','Граница «Вызывает»/«Помогает» пока качественная: возникновение результата и облегчение действия могут пересекаться. Автоматически переносить все причины в помощь нельзя. Действующие и условные объяснения унаследованы из предыдущей разметки; они не стали строгими законами от пересчёта.','','## Число пар каждого типа','','| Тип | E02 | E03 | E04 | Сумма |','|---|---:|---:|---:|---:|']
for t in types:
 ns=[stats[c]['counts'][t] for c in sources];rows.append(f'| {t} | '+' | '.join(map(str,ns))+f' | {sum(ns)} |')
rows+=['','Сумма по типам может превышать число уникальных пар из-за пересечений. Сумма трёх пулов не является результатом сопоставления объединённой колоды из 300 слов.','','## Охват и повторение типов на одной паре','','| Метрика | E02 | E03 | E04 |','|---|---:|---:|---:|']
metrics={'Уникальных пар':lambda s:len(s['pairs']),'Сумма пар по типам':lambda s:sum(s['counts'].values()),'Направленных объяснений':lambda s:s['annotations'],'Пар с несколькими типами':lambda s:s['multiple'],'Слов с хотя бы одной парой':lambda s:len(s['degree']),'Слов без найденных пар':lambda s:100-len(s['degree'])}
for title,fn in metrics.items():rows.append(f'| {title} | '+' | '.join(str(fn(stats[c])) for c in sources)+' |')
rows+=['','## Все 15 пересечений типов','','Пересечение — одна и та же неупорядоченная пара с обоими типами. Направления могут отличаться.','','| Тип 1 | Тип 2 | E02 | E03 | E04 | Сумма |','|---|---|---:|---:|---:|---:|']
for t,u in combinations(types,2):
 ns=[stats[c]['intersections'][t,u] for c in sources];rows.append(f'| {t} | {u} | '+' | '.join(map(str,ns))+f' | {sum(ns)} |')
rows+=['','## Исправления исходной разметки','','| Пул | Пара и прежний тип | Почему исключена |','|---|---|---|']
for c,e,why in removed:rows.append(f"| {c} | {e['a']} → {e['b']}: {e['type']} | {why} |")
rows+=['','Исходные JSON и отчёты не переписаны: новая версия хранится отдельно. В E02 направление характеристики приведено к носитель → признак; на неупорядоченные количества это не влияет.','','## Дополнительная проверка «Регулирует»','','В E02 добавлены три условные пары «Порядок → Подготовка / Тренировка / Проверка». Требуется именно заданный порядок действий. Если допускать только юридические или социальные нормы, эти три пары следует убрать: E02 тогда имеет ноль пар регулирования.','','В E03 отдельной пары регулирования не добавлено. «Совет» рекомендует, но сам по себе не устанавливает обязательный порядок; «Решение» означает нахождение ответа, а не управляющее решение. «Время» не подменяется отсутствующими «Расписанием» или «Сроком». Физическую регуляцию и управление скоростью не включаем без отдельного решения о расширении типа.','','В E04 сохранены 15 условно-нормативных пар. В девяти источником является «Правило»; по две исходят от «Запрета» и «Разрешения», по одной от «Права» и «Обязанности». Это концентрация типа на небольшой группе слов, а не равномерное распределение по колоде.','','## Доли с учётом пересечений','','Каждая уникальная пара даёт суммарный вес 1. Если у неё k типов, каждый получает 1/k. Доли описывают разметку, а не полный граф всех допустимых объяснений.','','| Тип | E02 | E03 | E04 | Все три пула |','|---|---:|---:|---:|---:|']
totalpairs=sum(len(s['pairs']) for s in stats.values())
for t in types:
 weights=[sum(1/len(ts) for ts in stats[c]['pairs'].values() if t in ts) for c in sources]
 vals=[f'{100*w/len(stats[c]["pairs"]):.1f}%' for w,c in zip(weights,sources)]
 rows.append(f'| {t} | '+' | '.join(vals)+f' | {100*sum(weights)/totalpairs:.1f}% |')
for c in sources:
 s=stats[c];rows+=['',f'## {c}: пары с несколькими выбранными типами','','| Пара | Типы |','|---|---|']
 for (a,b),ts in sorted(s['pairs'].items()):
  if len(ts)>1:rows.append(f'| {a} ↔ {b} | '+ '; '.join(sorted(ts))+' |')
 rows+=['',f'### {c}: слова по числу соседей','','| Слово | Уникальных соседей |','|---|---:|']
 for w in sorted(all_data[c]['words'],key=lambda w:(-s['degree'][w],w)):rows.append(f'| {w} | {s["degree"][w]} |')
 rows+=['',f'### {c}: реестр выбранных объяснений','','| A | Тип | B | Объяснение | Источник |','|---|---|---|---|---|']
 for e in all_data[c]['relations']:rows.append(f"| {e['a']} | {e['type']} | {e['b']} | {e['reason']} | {e['origin']} |")
(root/'six-types-comparison.md').write_text('\n'.join(rows)+'\n')
(root/'six-types-comparison.json').write_text(json.dumps(dict(status='review_of_partial_annotations',types=types,datasets=all_data),ensure_ascii=False,indent=2)+'\n')
print(json.dumps({c:dict(counts=s['counts'],unique_pairs=len(s['pairs']),multiple=s['multiple'],covered=len(s['degree']),overlaps={t+' / '+u:n for (t,u),n in s['intersections'].items() if n}) for c,s in stats.items()},ensure_ascii=False,indent=2))
assert len(removed)==len(exclude)
assert all(sum(s['counts'].values())==sum(len(ts) for ts in s['pairs'].values()) for s in stats.values())
